def assign_to_vik(apps, schema_editor):
    """Data som fanst før organisasjonar vart innført, blir lagt i området «Vik»:
    Vik kommune eig anlegga og fordeler tida i hallen, Vik IL fordeler tida på banane og eig laga."""
    Workspace = apps.get_model("bookings", "Workspace")
    Organization = apps.get_model("bookings", "Organization")
    Facility = apps.get_model("bookings", "Facility")
    Group = apps.get_model("bookings", "Group")
    AccountRequest = apps.get_model("bookings", "AccountRequest")
    if not (Facility.objects.exists() or Group.objects.exists() or AccountRequest.objects.exists()):
        return
    vik, _ = Workspace.objects.get_or_create(slug="vik", defaults={"name": "Vik"})
    kommune, _ = Organization.objects.get_or_create(workspace=vik, slug="vik-kommune",
                                                    defaults={"name": "Vik kommune", "kind": "kommune"})
    vikil, _ = Organization.objects.get_or_create(workspace=vik, slug="vikil",
                                                  defaults={"name": "Vik IL", "kind": "idrettslag"})
    for f in Facility.objects.filter(workspace__isnull=True):
        f.workspace = vik
        f.owner = kommune
        f.manager = kommune if f.kind == "hall" else vikil
        f.save()
    Group.objects.filter(organization__isnull=True).update(organization=vikil)
    AccountRequest.objects.filter(workspace__isnull=True).update(workspace=vik)


